    pg.evaluate("sbToggle()")
    eq('plegada, «Gestionar» se oculta', pg.evaluate("getComputedStyle(document.querySelector('.mgb')).display"), 'none'); pg.evaluate("sbToggle()")
    # ---- Fase 3
