    eq('la pestaña de clasificación usa el diseño de Ver todo (bloques plegables)', pg.evaluate("[...document.querySelectorAll('#dlg details.cs > summary')].map(s => s.textContent)"), ['Secciones', 'Etiquetas', 'Relacionados'])
